// src/ui/dashboard/common.ts
var import_obsidian5 = require("obsidian");
function sectionTitle(parent, text, action) {
  const row2 = parent.createDiv({ cls: "tp-dash-section-head" });
  row2.createDiv({ cls: "tp-dash-section-title", text });
  if (action) {
    const btn = row2.createEl("button", { cls: "tp-dash-action" });
    (0, import_obsidian5.setIcon)(btn.createSpan(), action.icon);
    btn.createSpan({ text: action.label });
    btn.addEventListener("click", action.onClick);
  }
  return row2;
}
function statTiles(parent, stats) {
  const grid = parent.createDiv({ cls: "tp-stat-grid" });
  for (const stat of stats) {
    const tile = grid.createDiv({ cls: `tp-stat is-${stat.tone ?? "default"}` });
    if (stat.icon) (0, import_obsidian5.setIcon)(tile.createDiv({ cls: "tp-stat-icon" }), stat.icon);
    tile.createDiv({ cls: "tp-stat-value", text: stat.value });
    tile.createDiv({ cls: "tp-stat-label", text: stat.label });
    if (stat.detail) tile.createDiv({ cls: "tp-stat-detail", text: stat.detail });
  }
}
function bar(parent, ratio, tone) {
  const track = parent.createDiv({ cls: "tp-bar-track" });
  const clamped = Math.max(0, Math.min(1, ratio));
  const fill = track.createDiv({ cls: `tp-bar-fill is-${tone ?? "good"}` });
  fill.style.width = `${Math.round(clamped * 100)}%`;
}
function emptyState(parent, icon, title, detail, actions = []) {
  const box = parent.createDiv({ cls: "tp-dash-empty" });
  (0, import_obsidian5.setIcon)(box.createDiv({ cls: "tp-dash-empty-icon" }), icon);
  box.createDiv({ cls: "tp-dash-empty-title", text: title });
  box.createDiv({ cls: "tp-dash-empty-detail", text: detail });
  if (actions.length === 0) return;
  const row2 = box.createDiv({ cls: "tp-dash-empty-actions" });
  for (const [index, action] of actions.entries()) {
    const btn = row2.createEl("button", {
      cls: index === 0 ? "tp-dash-empty-btn is-cta" : "tp-dash-empty-btn"
    });
    if (action.icon) (0, import_obsidian5.setIcon)(btn.createSpan(), action.icon);
    btn.createSpan({ text: action.label });
    btn.addEventListener("click", action.onClick);
  }
}
function noTripState(parent, ctx, icon) {
  const any = ctx.plugin.store.getTrips().length > 0;
  if (any) {
    emptyState(parent, icon, "No trip selected", "Pick a trip from the dropdown above.");
    return;
  }
  emptyState(parent, icon, "No trips yet", "Create your first trip to get started.", [
    { label: "New trip", icon: "plus", onClick: () => ctx.plugin.openNewTripModal() }
  ]);
}
function renderToolbar(parent, actions) {
  const toolbar = parent.createDiv({ cls: "tp-dash-toolbar" });
  for (const action of actions) {
    const btn = toolbar.createEl("button", { cls: "tp-dash-add" });
    if (action.icon) (0, import_obsidian5.setIcon)(btn.createSpan(), action.icon);
    btn.createSpan({ text: action.label });
    btn.addEventListener("click", action.onClick);
  }
}
function stateMark(state) {
  if (state === "complete") return { icon: "check", label: "Done" };
  if (state === "started") return { icon: "minus", label: "In progress" };
  return { icon: "x", label: "Not started" };
}
function readiness(plugin, trip) {
  const subNotes = plugin.store.getSubNotes(trip);
  let done = 0;
  let total = 0;
  for (const sub of subNotes) {
    const progress = plugin.progress.peek(sub.file);
    if (!progress) continue;
    total += 1;
    if (progress.state !== "empty") done += 1;
  }
  const bookings = plugin.bookings.getBookings(trip);
  if (bookings.length > 0) {
    total += 1;
    if (bookings.some((b) => b.status === "booked")) done += 1;
  }
  return { done, total, ratio: total === 0 ? 0 : done / total };
}

// src/ui/dashboard/gettingAround.ts
var import_obsidian6 = require("obsidian");

// src/travel/types.ts
var TRAVEL_MODES = [
  { id: "driving", label: "Car", icon: "car" },
  { id: "transit", label: "Public transport", icon: "train-front" },
  { id: "walking", label: "Walking", icon: "footprints" }
];
function parseLocation(value) {
  if (typeof value !== "string") return null;
  const parts = value.split(",");
  if (parts.length !== 2) return null;
  const lat = Number(parts[0].trim());
  const lng = Number(parts[1].trim());
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  if (Math.abs(lat) > 90 || Math.abs(lng) > 180) return null;
  return { lat, lng };
}
function formatLocation(coord) {
  return `${coord.lat},${coord.lng}`;
}
function coordKey(coord) {
  return `${coord.lat.toFixed(4)},${coord.lng.toFixed(4)}`;
}
function legKey(from, to, mode) {
  return `${coordKey(from)}|${coordKey(to)}|${mode}`;
}
function formatDuration2(seconds) {
  const mins = Math.round(seconds / 60);
  if (mins < 60) return `${mins} min`;
  const hours = Math.floor(mins / 60);
  const rest = mins % 60;
  return rest === 0 ? `${hours} h` : `${hours} h ${rest} min`;
}
function formatDistance(meters) {
  if (meters < 1e3) return `${Math.round(meters / 10) * 10} m`;
  const km = meters / 1e3;
  return km < 10 ? `${km.toFixed(1)} km` : `${Math.round(km)} km`;
}

// src/ui/dashboard/gettingAround.ts
var MODE_ICON = new Map(TRAVEL_MODES.map((m) => [m.id, m.icon]));
function renderGettingAround(parent, ctx) {
  const { trip, plugin } = ctx;
  if (!trip) return;
  const travel = plugin.travel;
  if (!travel.isConfigured()) {
    if (!plugin.settings.travelTimesEnabled) return;
    sectionTitle(parent, "Getting around");
    parent.createDiv({
      cls: "tp-dash-hint",
      text: "Add a Google API key in Travel Planner settings to see travel times."
    });
    return;
  }
  const places = plugin.travelPlaces.get(trip.folderPath);
  if (!places) {
    sectionTitle(parent, "Getting around", {
      label: "Calculate",
      icon: "route",
      onClick: () => void plugin.computeTravelTimes(trip, ctx.refresh)
    });
    parent.createDiv({
      cls: "tp-dash-hint",
      text: "Work out how far the hotel is from the airport, your activities and your restaurants."
    });
    return;
  }
  const origin = places.hotels[0];
  if (!origin) {
    sectionTitle(parent, "Getting around");
    parent.createDiv({
      cls: "tp-dash-hint",
      text: "Add an accommodation booking \u2014 distances are measured from where you're staying."
    });
    return;
  }
  sectionTitle(parent, `Getting around \xB7 from ${origin.label}`, {
    label: "Refresh",
    icon: "refresh-cw",
    onClick: () => void plugin.computeTravelTimes(trip, ctx.refresh, true)
  });
  const modes = plugin.settings.travelModes;
  const groups = [
    { title: "Airport", items: places.airports },
    { title: "Activities", items: places.activities },
    { title: "Restaurants", items: places.restaurants }
  ];
  let rendered = 0;
  for (const group of groups) {
    if (group.items.length === 0) continue;
    const legs = travel.peekLegs(origin, group.items, modes);
    if (legs.size === 0) continue;
    rendered += 1;
    parent.createDiv({ cls: "tp-around-group", text: group.title });
    const list3 = parent.createDiv({ cls: "tp-around-list" });
    const sorted = [...group.items].sort((a, b) => shortest(legs.get(a.id)) - shortest(legs.get(b.id)));
    for (const place of sorted) {
      const placeLegs = legs.get(place.id);
      if (!placeLegs) continue;
      renderRow(list3, place, placeLegs, ctx);
    }
  }
  if (rendered === 0) {
    parent.createDiv({
      cls: "tp-dash-hint",
      text: "No routes found yet. Try Refresh, or check that the addresses on your bookings are specific enough to find."
    });
  }
}
function shortest(legs) {
  if (!legs || legs.length === 0) return Number.MAX_SAFE_INTEGER;
  return Math.min(...legs.map((l) => l.durationSeconds));
}
function renderRow(parent, place, legs, ctx) {
  const row2 = parent.createDiv({ cls: "tp-around-row" });
  const text = row2.createDiv({ cls: "tp-around-text" });
  text.createDiv({ cls: "tp-around-name", text: place.label });
  const walking = legs.find((l) => l.mode === "walking");
  const driving = legs.find((l) => l.mode === "driving");
  const reference = walking ?? driving ?? legs[0];
  if (reference) {
    text.createDiv({ cls: "tp-around-dist", text: formatDistance(reference.distanceMeters) });
  }
  const times2 = row2.createDiv({ cls: "tp-around-times" });
  for (const leg of legs) {
    const chip = times2.createDiv({ cls: `tp-around-chip is-${leg.mode}` });
    (0, import_obsidian6.setIcon)(chip.createSpan({ cls: "tp-around-chip-icon" }), MODE_ICON.get(leg.mode) ?? "route");
    chip.createSpan({ text: formatDuration2(leg.durationSeconds) });
    chip.setAttribute(
      "aria-label",
      `${TRAVEL_MODES.find((m) => m.id === leg.mode)?.label ?? leg.mode}: ${formatDistance(leg.distanceMeters)}`
    );
  }
  if (place.file) {
    row2.addClass("is-clickable");
    row2.addEventListener("click", () => ctx.openFile(place.file));
  }
}
function travelTable(origin, destinations, legs, modes) {
  const usable = destinations.filter((d) => legs.has(d.id));
  if (usable.length === 0) return "";
  const header = ["| Destination | Distance |", "|---|---|"];
  const columns = modes.filter(
    (mode) => usable.some((d) => legs.get(d.id)?.some((l) => l.mode === mode))
  );
  for (const mode of columns) {
    const label = TRAVEL_MODES.find((m) => m.id === mode)?.label ?? mode;
    header[0] += ` ${label} |`;
    header[1] += "---|";
  }
  const rows = usable.sort((a, b) => shortest(legs.get(a.id)) - shortest(legs.get(b.id))).map((place) => {
    const placeLegs = legs.get(place.id) ?? [];
    const reference = placeLegs.find((l) => l.mode === "walking") ?? placeLegs[0];
    let row2 = `| ${place.label} | ${reference ? formatDistance(reference.distanceMeters) : "\u2014"} |`;
    for (const mode of columns) {
      const leg = placeLegs.find((l) => l.mode === mode);
      row2 += ` ${leg ? formatDuration2(leg.durationSeconds) : "\u2014"} |`;
    }
    return row2;
  });
  return [`### From ${origin.label}`, "", ...header, ...rows, ""].join("\n");
}

