var import_obsidian10 = require("obsidian");
function showTripMenu(evt, trip, ctx) {
  const { plugin } = ctx;
  const menu = new import_obsidian10.Menu();
  menu.addItem(
    (item) => item.setTitle("Open trip note").setIcon("file-text").onClick(() => ctx.openFile(trip.file))
  );
  const subNotes = plugin.store.getSubNotes(trip);
  if (subNotes.length > 0) {
    menu.addSeparator();
    for (const sub of subNotes) {
      menu.addItem(
        (item) => item.setTitle(sub.label).setIcon("file-text").onClick(() => ctx.openFile(sub.file))
      );
    }
  }
  menu.addSeparator();
  for (const def of BOOKING_KINDS) {
    menu.addItem(
      (item) => item.setTitle(`Add ${def.label.toLowerCase()}`).setIcon(def.icon).onClick(() => plugin.openBookingWizard(trip, def.id))
    );
  }
  menu.addItem(
    (item) => item.setTitle("Log an expense").setIcon("receipt").onClick(() => plugin.openExpenseModal(trip))
  );
  menu.addItem(
    (item) => item.setTitle("Add itinerary day").setIcon("calendar-plus").onClick(() => plugin.openAddDayModal(trip))
  );
  menu.addSeparator();
  menu.addItem(
    (item) => item.setTitle("Edit trip\u2026").setIcon("pencil").onClick(() => plugin.openEditTripModal(trip))
  );
  menu.addItem(
    (item) => item.setTitle("Set budget\u2026").setIcon("sliders-horizontal").onClick(() => plugin.openBudgetModal(trip))
  );
  if (plugin.travel.isConfigured()) {
    menu.addItem(
      (item) => item.setTitle("Calculate travel times").setIcon("route").onClick(() => void plugin.computeTravelTimes(trip, ctx.refresh))
    );
  }
  menu.addItem(
    (item) => item.setTitle("Copy folder path").setIcon("clipboard-copy").onClick(async () => {
      await navigator.clipboard.writeText(trip.folderPath);
      new import_obsidian10.Notice(`Copied ${trip.folderPath}`);
    })
  );
  menu.addSeparator();
  menu.addItem(
    (item) => item.setTitle("Delete trip\u2026").setIcon("trash-2").onClick(() => plugin.deleteTrip(trip))
  );
  menu.showAtMouseEvent(evt);
}

// src/ui/dashboard/tabs/trips.ts
function renderAllTripsSummary(parent, ctx, trips) {
  const { plugin } = ctx;
  const upcoming = trips.filter((t) => t.status === "upcoming");
  const current = trips.filter((t) => t.status === "current");
  const spend = sumMoney(
    trips.flatMap((t) => plugin.bookings.getCostLines(t).filter((l) => l.counted).map((l) => l.money))
  );
  let unfinished = 0;
  for (const trip of [...current, ...upcoming]) {
    const ready = readiness(plugin, trip);
    if (ready.total > 0 && ready.ratio < 1) unfinished += 1;
  }
  const next = current[0] ?? upcoming[0];
  const until = next ? daysUntil(next.startDate) : null;
  statTiles(parent, [
    {
      label: "Trips",
      value: String(trips.length),
      detail: `${upcoming.length} upcoming \xB7 ${trips.length - upcoming.length - current.length} past`,
      icon: "plane"
    },
    {
      label: next ? "Next trip" : "Next trip",
      value: !next ? "\u2014" : current.length > 0 ? "Now" : until === null ? "\u2014" : `${until}d`,
      detail: next ? next.title : "Nothing planned",
      icon: "calendar-days"
    },
    {
      label: "Total spend",
      value: formatTotals(spend, "\u2014"),
      detail: "Across every trip",
      icon: "wallet"
    },
    {
      label: "Need attention",
      value: String(unfinished),
      detail: unfinished === 0 ? "All up to date" : "Trips with notes still empty",
      icon: "alert-circle",
      tone: unfinished > 0 ? "warn" : "good"
    }
  ]);
}
