var import_obsidian22 = require("obsidian");
async function replaceSection(app, file, heading, body) {
  const content = await app.vault.read(file);
  const lines2 = content.split("\n");
  const start = lines2.findIndex((line) => line.trim() === `## ${heading}`);
  const block = `## ${heading}

${body.trimEnd()}
`;
  if (start === -1) {
    await app.vault.modify(file, `${content.trimEnd()}

${block}`);
    return;
  }
  let end = lines2.length;
  for (let i = start + 1; i < lines2.length; i += 1) {
    if (/^#{1,2}\s/.test(lines2[i])) {
      end = i;
      break;
    }
  }
  const next = [...lines2.slice(0, start), block, ...lines2.slice(end)].join("\n");
  await app.vault.modify(file, next.replace(/\n{3,}/g, "\n\n"));
}
async function appendTableRow(app, file, heading, header, cells) {
  const content = await app.vault.read(file);
  const lines2 = content.split("\n");
  const row2 = `| ${cells.join(" | ")} |`;
  const start = lines2.findIndex((line) => line.trim() === `## ${heading}`);
  if (start === -1) {
    const table = [
      `## ${heading}`,
      "",
      `| ${header.join(" | ")} |`,
      `|${header.map(() => "---").join("|")}|`,
      row2,
      ""
    ].join("\n");
    await app.vault.modify(file, `${content.trimEnd()}

${table}`);
    return;
  }
  let end = lines2.length;
  for (let i = start + 1; i < lines2.length; i += 1) {
    if (/^#{1,2}\s/.test(lines2[i])) {
      end = i;
      break;
    }
  }
  let lastTableLine = -1;
  for (let i = start + 1; i < end; i += 1) {
    if (lines2[i].trim().startsWith("|")) lastTableLine = i;
  }
  if (lastTableLine === -1) {
    const table = [`| ${header.join(" | ")} |`, `|${header.map(() => "---").join("|")}|`, row2];
    lines2.splice(start + 1, 0, "", ...table);
  } else {
    const isBlankRow = (line) => line.trim().startsWith("|") && line.split("|").slice(1, -1).every((c) => c.trim() === "");
    if (isBlankRow(lines2[lastTableLine])) lines2.splice(lastTableLine, 1, row2);
    else lines2.splice(lastTableLine + 1, 0, row2);
  }
  await app.vault.modify(file, lines2.join("\n"));
}
function subNoteFile(app, trip, id) {
  const path = `${trip.folderPath}/${SUB_NOTE_LABELS[id]}.md`;
  const file = app.vault.getAbstractFileByPath(path);
  return file instanceof import_obsidian22.TFile ? file : null;
}
async function ensureSubNote(app, trip, id) {
  const existing = subNoteFile(app, trip, id);
  if (existing) return existing;
  const path = `${trip.folderPath}/${SUB_NOTE_LABELS[id]}.md`;
  const file = await app.vault.create(path, "");
  await app.fileManager.processFrontMatter(file, (fm) => {
    fm.type = id;
    fm.trip = app.fileManager.generateMarkdownLink(trip.file, path);
  });
  const head = await app.vault.read(file);
  await app.vault.modify(file, `${head.trimEnd()}

# ${SUB_NOTE_LABELS[id]} \u2014 ${trip.title}
`);
  return file;
}

